// Browser-local, explicit research records. No network or automatic upload.
export const NOTEBOOK_VERSION=1;
export const RELEASE='20261113-route1';
export const MAX_PROJECT_BYTES=32*1024*1024;
const ACTIONS=new Set('layer_symmetry_lab chirality_polarity_lab manybody_spt_lab symmetry_audit statistics_lab defects_lab reciprocity_lab salc_lab wavevector_lab nonsymmorphic_lab order_parameter_lab exchange_symmetry_lab conservation_lab manybody_spectra_lab polaron_lab density_matrix_lab symmetry_workshop band_rep_lab dynamic_scattering_lab domain_wall_lab hubbard_lab analyze induce product match_bands magnetictb crystkit symbolic carat crystkit_ext carat_integral integral_normalizer symbolic_interfaces arithmetic_centralizer symbolic_spacegroups structure_bc standard_labels teaching_labs phonons tensors phase diffraction phonopy phonon_modes band_connectivity phonon_thermo distortion_lab magnon_lab qha_lab pairing_lab shg_lab unfold_lab crystal_field_lab quantum_geometry_lab electron_transport_lab hall_response_lab device_transport_lab local_multiplet_lab spin_resonance_lab andreev_lab atomic_spectra_lab'.split(' '));
const PROGRESS=['shg-flagship.progress','frontiers.progress','frontiers.predictions','frontiers.assignments','connections.progress','connections.predictions','connections.assignments','construction.progress','construction.predictions','construction.assignments','principles.progress','principles.predictions','bridges.progress','bridges.predictions','pathways.progress','pointgroups.progress','academy.progress','academy.derivations','lie.progress','lie.derivations','observables.progress','structure-dynamics.progress','material-research.progress','coupled-materials.progress','electronic-materials.progress','quantum-materials.progress','response-materials.progress','spectroscopy.progress'].map(x=>'symmetry-lab.'+x+'.v1');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const object=x=>x&&typeof x==='object'&&!Array.isArray(x);
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
const clone=x=>JSON.parse(JSON.stringify(x));
const bytes=x=>new TextEncoder().encode(typeof x==='string'?x:JSON.stringify(x)).length;
let latest=null,dbPromise,storageWarning='';
const memory=new Map();
export function validateJSON(value,depth=0,counter={n:0}){
 if(depth>60||++counter.n>1500000)throw Error("The research record has too many data levels or items.");
 if(value===null||typeof value==='string'||typeof value==='boolean')return;
 if(typeof value==='number'){if(!Number.isFinite(value))throw Error("research record contains non-finite values");return;}
 if(typeof value!=='object')throw Error("research records must be JSON data");
 for(const [key,item] of Object.entries(value)){if(['__proto__','prototype','constructor'].includes(key))throw Error("Research record contains an object key that is not allowed");validateJSON(item,depth+1,counter);}
}
export function safeRecordRoute(route){return typeof route==='string'&&route.length<=1000&&/^(?:compute(?:\/|$)|classroom(?:\/|\?|$)|atlas(?:\/|\?|$)|structure(?:\?|$)|workbench(?:\?|$)|products(?:\?|$)|bands(?:\?|$)|magnetictb(?:\?|$)|crystkit(?:\?|$)|advanced(?:\?|$))[a-zA-Z0-9_/?=&.%+\-]*$/.test(route)?route:'compute';}
export function captureCalculation(action,input,result,context={}){
 latest=null;if(!ACTIONS.has(action))return;
 try{validateJSON(input);validateJSON(result);if(!object(input)||!object(result))throw Error("calculation input and results must be JSON objects");const record={id:uid(),action,input:clone(input),result:clone(result),route:safeRecordRoute(context.route),title:String(context.title||action).slice(0,160),material:String(context.material||'').slice(0,120),created:new Date().toISOString(),release:RELEASE,notes:''};validateJSON(record);if(bytes(record)>MAX_PROJECT_BYTES)throw Error("The calculated data exceeds 32 MiB for a single project, please use the calculator to export the results");latest=record;return record;}catch(error){latest=null;storageWarning=error.message;}
}
export const latestCalculation=()=>latest?clone(latest):null;
function validateProgress(snapshot){validateJSON(snapshot);if(!object(snapshot))throw Error("learning progress snapshot must be JSON object");for(const [key,value]of Object.entries(snapshot)){if(!PROGRESS.includes(key))throw Error("project contains unknown learning progress key");if(!object(value)||bytes(value)>200000)throw Error("The learning progress of each group must be JSON objects that do not exceed 200 kB");}return snapshot;}
export function progressSnapshot(){const result={};for(const key of PROGRESS){try{const raw=localStorage.getItem(key);if(raw&&bytes(raw)<=200000){const value=JSON.parse(raw);validateProgress({[key]:value});result[key]=value;}}catch{}}return result;}
export function restoreProgress(snapshot){
 validateProgress(snapshot);const updates=Object.entries(snapshot).map(([key,value])=>[key,JSON.stringify(value)]),backup=new Map(updates.map(([key])=>[key,localStorage.getItem(key)])),written=[];
 try{for(const [key,value]of updates){localStorage.setItem(key,value);written.push(key);}}catch(error){let rollbackFailed=false;for(const key of written.reverse()){try{const old=backup.get(key);if(old===null)localStorage.removeItem(key);else localStorage.setItem(key,old);}catch{rollbackFailed=true;}}throw Error(rollbackFailed?"Learning progress writing failed, and some old values cannot be restored; please keep a backup of the project and check the browser storage.":"The learning progress writing failed and the original progress has been restored; please check the browser storage space.");}return updates.length;
}
export function makeProject({title="My Materials Research",material='',notes=''}={}){return {format:'symmetry-lab-material-project',version:NOTEBOOK_VERSION,id:uid(),title:String(title).slice(0,160),material:String(material).slice(0,120),notes:String(notes).slice(0,20000),created:new Date().toISOString(),updated:new Date().toISOString(),release:RELEASE,records:[],progress:{}};}
export function validateProject(project){
 validateJSON(project);if(!object(project)||project.format!=='symmetry-lab-material-project'||project.version!==NOTEBOOK_VERSION)throw Error("is not a supported Symmetry Lab material item (version 1)");
 if(typeof project.id!=='string'||!project.id||project.id.length>100||typeof project.title!=='string'||project.title.length>160||typeof project.material!=='string'||project.material.length>120||typeof project.notes!=='string'||project.notes.length>20000)throw Error("The project name, materials or notes are not in the correct format");
 if(!Array.isArray(project.records)||project.records.length>40||!object(project.progress))throw Error("Save up to 40 calculations per material item");
 for(const key of ['created','updated','release'])if(typeof project[key]!=='string'||project[key].length>100)throw Error("The project date or version format is incorrect");
 const ids=new Set();for(const r of project.records){if(!object(r)||typeof r.id!=='string'||!r.id||r.id.length>100||ids.has(r.id)||!ACTIONS.has(r.action)||!object(r.input)||!object(r.result)||typeof r.title!=='string'||r.title.length>160||typeof r.notes!=='string'||r.notes.length>20000||r.route!==safeRecordRoute(r.route))throw Error("project is incomplete or contains unsupported tools");for(const key of ['created','release'])if(typeof r[key]!=='string'||r[key].length>100)throw Error("The calculation record date or version format is incorrect");if(r.material!==undefined&&(typeof r.material!=='string'||r.material.length>120))throw Error("The calculation record material label format is incorrect.");if(r.draftInput!==undefined&&(typeof r.draftInput!=='string'||bytes(r.draftInput)>MAX_PROJECT_BYTES))throw Error("Recalculation input draft must be no more than 32 MiB of text");ids.add(r.id);}
 if(project.assignment!==undefined){
  const a=project.assignment;if(!object(a)||!['surface-to-polarity','chirality-to-optics','schmidt-to-spt','pauli-to-hubbard','manifold-to-wall','reciprocity-to-hall','geometry-hall','ssh-device','orbital-multiplet','spin-resonance','normal-andreev','multiplet-xas','site-bloch-little-group','bose-scattering','bulk-interface-localization','hund-superexchange','levels-to-manybody-spectra','vibration-cloud-reduced-state','spin-coupling-decoherence','symmetry-to-bands','order-to-bond-constraints','bond-to-conserved-spin','generator-to-dephasing','salc-to-fourier-star','order-to-nonsymmorphic-mass','site-to-spinful-screw'].includes(a.id)||!object(a.steps)||Object.keys(a.steps).length>12||typeof a.conclusion!=='string'||a.conclusion.length>12000)throw Error("Project job metadata is incomplete");
  const allowed={'surface-to-polarity':['slab','surface','order'],'chirality-to-optics':['chiral','polar','optics'],'schmidt-to-spt':['density','periodic','edge'],'pauli-to-hubbard':['allowed','forbidden','energy'],'manifold-to-wall':['loop','pair','wall'],'reciprocity-to-hall':['full','partial','bands'],'salc-to-fourier-star':['local','copies','star'],'order-to-nonsymmorphic-mass':['pattern','unbroken','mass'],'site-to-spinful-screw':['induced','single','double'], 'geometry-hall':['geometry','plateau','metal'],'ssh-device':['bulk','weak','strong'],'orbital-multiplet':['orbitals','high','low'],'spin-resonance':['ion','isotropic','split'],'normal-andreev':['normal','delta0','paired'],'multiplet-xas':['kanamori','linearx','linearz'],'site-bloch-little-group':['gamma','boundary','little'],'bose-scattering':['thermal','cold','warm'],'bulk-interface-localization':['bulk','wall','potential'],'hund-superexchange':['hund','dimer','strong'],'levels-to-manybody-spectra':['ground','addition','response'],'vibration-cloud-reduced-state':['free','cloud','classical'],'spin-coupling-decoherence':['cg','exchange','noise'],'symmetry-to-bands':['allowed','inversion','lattice'],'order-to-bond-constraints':['direction','bond','convention'],'bond-to-conserved-spin':['dmi','inversion','generators'],'generator-to-dephasing':['unitary','bath','density'] };
  for(const [key,step]of Object.entries(a.steps)){if(!allowed[a.id].includes(key)||!object(step)||typeof step.recordId!=='string'||(step.recordId!==''&&!ids.has(step.recordId))||typeof step.interpretation!=='string'||step.interpretation.length>8000)throw Error("Invalid project stage or referenced calculation record");}
 }
 validateProgress(project.progress);
 if(bytes(project)>MAX_PROJECT_BYTES)throw Error("project exceeds 32 MiB, please split it into multiple projects");return project;
}
export function importProject(text){if(bytes(text)>MAX_PROJECT_BYTES)throw Error("import file exceeds 32 MiB");const p=validateProject(JSON.parse(text));const copy=clone(p);copy.id=uid();copy.title=(copy.title+" · Import copy").slice(0,160);copy.updated=new Date().toISOString();return copy;}
export function addRecord(project,record){validateProject(project);if(!record)throw Error("Please complete the calculation first");validateJSON(record);const p=clone(project);p.records.push({...clone(record),id:uid()});p.updated=new Date().toISOString();p.progress=progressSnapshot();return validateProject(p);}
async function db(){if(!dbPromise)dbPromise=new Promise(resolve=>{if(!globalThis.indexedDB){storageWarning="The current environment does not support persistent storage, and the records are only left on this page; please export the project backup.";return resolve(null);}try{const req=indexedDB.open('symmetry-lab-material-notebook',1);req.onupgradeneeded=()=>req.result.createObjectStore('projects',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>{storageWarning="Local storage is unavailable, the record is only left on this page; please export the project backup.";resolve(null);};req.onblocked=()=>{storageWarning="The local database is occupied by other pages. This page is temporarily stored. Please export the backup.";resolve(null);};}catch{storageWarning="The browser blocks local storage, please export the project backup.";resolve(null);}});return dbPromise;}
export async function saveProject(project){validateProject(project);const value=clone(project);memory.set(value.id,value);const database=await db();if(!database)return value;try{await new Promise((resolve,reject)=>{const tx=database.transaction('projects','readwrite');tx.objectStore('projects').put(value);tx.oncomplete=resolve;tx.onerror=()=>reject(Error("Local saving failed, there may be insufficient storage space; please export the project first."));tx.onabort=()=>reject(Error("Local saving is not completed; please export the project backup."));});memory.delete(value.id);}catch(error){storageWarning="The saving is not completed; the latest content is retained in the memory of this page. Please export the project backup and then refresh.";throw error;}return value;}
export async function listProjects(){const database=await db();let values=[];if(database){try{values=await new Promise((resolve,reject)=>{const req=database.transaction('projects').objectStore('projects').getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(Error("Unable to read local material items"));});}catch(error){if(!memory.size)throw error;storageWarning="The local database failed to read; only the items retained on this page are displayed here. Please export the backup first.";}}const merged=new Map(values.map(value=>[value.id,value]));for(const [id,value]of memory)merged.set(id,value);return clone([...merged.values()]).sort((a,b)=>String(b.updated).localeCompare(String(a.updated)));}
export async function renderMaterialNotebook({container,run,cancelRun,download,toast=()=>{},reload=null}){
 container.innerHTML="<div class=\"obs-page notebook-page\"><p>is reading the material items of this machine...</p></div>";const root=container.firstElementChild,$=s=>root.querySelector(s),current=()=>root.parentNode===container&&container.isConnected!==false;
 let projects=[];try{projects=await listProjects();}catch(error){storageWarning=error.message+"; The original database has not been changed. You can import the backup or create a new project and try again.";}let project=projects[0]||null,selected=project?.records.at(-1)?.id,busy=false,operationBusy=false;
 const notice=text=>{if($('#nb-status'))$('#nb-status').textContent=text;};
 const save=async(target=project)=>{target.updated=new Date().toISOString();await saveProject(target);projects=await listProjects();};
 const edit=()=>{if(!project)return;for(const [field,id,limit]of [['title','nb-title',160],['material','nb-material',120],['notes','nb-notes',20000]])if($('#'+id))project[field]=$('#'+id).value.slice(0,limit);const record=project.records.find(r=>r.id===selected);if(record){if($('#nb-record-notes'))record.notes=$('#nb-record-notes').value.slice(0,20000);if($('#nb-rerun-input')){const text=$('#nb-rerun-input').value;if(bytes(text)>MAX_PROJECT_BYTES)throw Error("Recalculation input draft exceeds 32 MiB");if(text===JSON.stringify(record.input,null,2))delete record.draftInput;else record.draftInput=text;}}};
 const lock=()=>{if(!current())return;for(const tag of ['button','input','select','textarea'])root.querySelectorAll(tag).forEach(control=>{if(control.id!=='nb-cancel')control.disabled=operationBusy;});if($('#nb-cancel'))$('#nb-cancel').hidden=!busy;};
 async function perform(fn){if(operationBusy)return;operationBusy=true;try{edit();lock();await fn();}catch(e){if(current()){draw();notice(e.message);}}finally{operationBusy=false;lock();}}
 function draw(){if(!current())return;const recent=latestCalculation(),record=project?.records.find(r=>r.id===selected);root.innerHTML=`<header class="obs-header"><span class="obs-eyebrow">ONE MATERIAL · REPRODUCIBLE STEPS</span><h2>Materials Research Record</h2><p>Put the structure, coordinate conventions, raw inputs, calculation results, and your interpretation in the same project. Click Save to write to this browser, the file will not be uploaded.</p></header><div class="obs-links"><button id="nb-new" class="primary">+ New material project</button><label class="secondary">Import a copy of the project<input id="nb-import" type="file" accept=".json"></label></div><p id="nb-status" role="status">${esc(storageWarning||"local save and JSON backup are independent of each other; clearing website data will remove items from the browser.")}</p>${projects.length?`<label>Select material item<select id="nb-project">${projects.map(p=>`<option value="${esc(p.id)}" ${project?.id===p.id?'selected':''}>${esc(p.title)} · ${p.records.length} calculations</option>`).join('')}</select></label>`:''}${recent?`<aside class="obs-example"><h3>Most recently completed calculation:${esc(recent.title)}</h3><p>${esc(recent.action)} · ${esc(recent.created)} · ${esc(recent.release)}</p><button id="nb-add" class="secondary">Add this calculation to the current project</button></aside>`:"<p class=\"obs-model-note\">First complete a calculation in the calculation center, and then click \"Record latest calculation\". You can also import existing projects to continue research.</p>"}${project?`<div class="nb-metadata"><label>Project name<input id="nb-title" maxlength="160" value="${esc(project.title)}"></label><label>Materials and Phases (User Tag)<input id="nb-material" maxlength="120" value="${esc(project.material)}"></label><label>Research questions and conclusions<textarea id="nb-notes" rows="4" maxlength="20000">${esc(project.notes)}</textarea></label></div><div class="obs-links"><button id="nb-save" class="primary">Save projects and learning progress</button><button id="nb-export" class="secondary">↓ Export complete project JSON</button><button id="nb-progress" class="secondary">Resume the practice progress of this project</button></div><h3>calculation record · ${project.records.length} / 40</h3><div class="nb-records">${project.records.map((r,i)=>`<button class="${r.id===selected?'primary':'secondary'}" data-nb-record="${esc(r.id)}">${i+1}. ${esc(r.title)}<small>${esc(r.action)} · ${esc(r.release)}</small></button>`).join('')}</div>${record?`<article class="obs-lesson"><h3>${esc(record.title)}</h3><p>original calculation:${esc(record.created)} · ${esc(record.release)}. The saved data includes the units, model, and coordinate conventions returned by the tool; the current software version is ${RELEASE}。</p><label>Explanation of this calculation<textarea id="nb-record-notes" rows="3" maxlength="20000">${esc(record.notes)}</textarea></label><details><summary>Original input and parameters (can be copied; a modified recalculation record can be created below)</summary><pre>${esc(JSON.stringify(record.input,null,2))}</pre></details><details><summary>Edit this recalculation input JSON</summary><textarea id="nb-rerun-input" rows="10" spellcheck="false">${esc(record.draftInput??JSON.stringify(record.input,null,2))}</textarea></details><div class="obs-links"><button id="nb-rerun" class="secondary" ${busy?'disabled':''}> is recalculated as a new record using the current version</button><button id="nb-cancel" class="secondary" ${busy?'':'hidden'}> Cancel recalculation</button><button id="nb-save-record" class="secondary">Save explanation</button><a href="#${esc(record.route)}">Open the original tool →</a></div><details><summary>Full results</summary><pre>${esc(JSON.stringify(record.result,null,2))}</pre></details></article>`:"<p>There is no calculation record for the current project. Project notes and learning progress can still be saved.</p>"}`:''}<p class="obs-small">project up to 32 MiB / 40 calculations. Import creates a copy; recalculation creates new records, and the original results are retained. Project data and imported material content are not automatically published to GitHub.</p>`;
 $('#nb-new').onclick=()=>perform(async()=>{if(project)await save();project=makeProject();selected=null;await save();draw();});
 $('#nb-import').onchange=e=>perform(async()=>{const file=e.target.files?.[0];if(!file)return;if(file.size>MAX_PROJECT_BYTES)throw Error("import file exceeds 32 MiB");if(project)await save();const p=importProject(await file.text());await saveProject(p);projects=await listProjects();project=p;selected=p.records.at(-1)?.id;draw();notice("has been imported as a separate copy and the original project and its draft have been saved.");});
 if($('#nb-project'))$('#nb-project').onchange=e=>{const id=e.target.value;return perform(async()=>{if(project)await save();project=projects.find(p=>p.id===id);selected=project?.records.at(-1)?.id;draw();});};
 if($('#nb-add'))$('#nb-add').onclick=()=>perform(async()=>{if(!project)project=makeProject({material:recent.material});project=addRecord(project,recent);selected=project.records.at(-1).id;await save();draw();notice("The original input, results, software version and current exercise progress have been saved."+storageWarning);});
 if(!project)return;
 $('#nb-save').onclick=()=>perform(async()=>{project.progress=progressSnapshot();await save();notice("project saved."+storageWarning);});
 $('#nb-export').onclick=()=>perform(async()=>{project.progress=progressSnapshot();project.updated=new Date().toISOString();validateProject(project);download(JSON.stringify(project,null,2),'symmetry-material-project.json');notice("The complete project has been exported; this export does not rely on the browser database and can be imported and restored.");});
 $('#nb-progress').onclick=()=>perform(async()=>{await save();const count=restoreProgress(project.progress);if(!count){notice("There is no saved exercise progress for this project; the current progress has not been modified.");return;}notice("restored "+count+" Group practice progress, the class cache is being refreshed.");if(reload)await reload();else if(await db()&&!memory.size)globalThis.location?.reload?.();else notice("restored "+count+" group practice progress. The current project is only in the page memory. Please export all projects first, and then refresh the page to apply the classroom progress.");});
 root.querySelectorAll('[data-nb-record]').forEach(b=>b.onclick=()=>perform(async()=>{await save();selected=b.dataset.nbRecord;draw();}));
 if(!record)return;
 $('#nb-save-record').onclick=()=>perform(async()=>{await save();notice("Calculation explanation and recalculation input draft has been saved."+storageWarning);});
 $('#nb-cancel').onclick=()=>cancelRun?.();
 $('#nb-rerun').onclick=()=>perform(async()=>{const input=JSON.parse(record.draftInput??JSON.stringify(record.input));validateJSON(input);if(!object(input))throw Error("recalculation input must be JSON object");const targetProject=project,targetId=project.id,sourceRecord=clone(record);await save(targetProject);busy=true;lock();notice("Python is being recalculated; the current project is locked and the original record will be retained...");try{const result=await run(sourceRecord.action,input);validateJSON(result);const newRecord={...sourceRecord,id:uid(),input,result,created:new Date().toISOString(),release:RELEASE,title:(sourceRecord.title+" · Recalculation").slice(0,160),notes:"recorded by "+sourceRecord.id+" Recalculate; old results retained."};delete newRecord.draftInput;const updated=addRecord(targetProject,newRecord);if(project?.id===targetId){project=updated;selected=updated.records.at(-1).id;}await save(updated);if(current()){draw();notice("The recalculation is completed, and both the old and new results are saved."+storageWarning);}}finally{busy=false;lock();}});
 lock();
 }
 draw();
}
